"use client";

import { OverlayArrow } from "react-aria-components";
import { cx } from "./cx";

/** Arrow for Popover and Tooltip. It rotates to face the trigger. */
export function Arrow({ className }: { className?: string }) {
  return (
    <OverlayArrow>
      <svg
        width={12}
        height={12}
        viewBox="0 0 12 12"
        aria-hidden="true"
        className={cx(
          "block [[data-placement=bottom]>&]:rotate-180 [[data-placement=left]>&]:-rotate-90 [[data-placement=right]>&]:rotate-90",
          className,
        )}
      >
        <path d="M0 0 L6 6 L12 0" />
      </svg>
    </OverlayArrow>
  );
}

/** Joins class names, skipping falsy values. */
export function cx(...classes: Array<string | false | null | undefined>): string {
  return classes.filter(Boolean).join(" ");
}

// Shared styles for fields built from a Group of segments (DatePicker,
// DateRangePicker). They match TextField and Select visually.

export type FieldSize = "sm" | "md" | "lg";

export const fieldLabel = "text-sm font-medium text-[var(--rd-color-text-default)]";
export const fieldHelp = "text-xs text-[var(--rd-color-text-muted)]";
export const fieldError = "text-xs text-[var(--rd-color-feedback-danger)]";

export const fieldGroup =
  "flex w-full items-center gap-1 bg-[var(--rd-color-surface-default)] text-[var(--rd-color-text-default)] " +
  "border border-[var(--rd-color-border-default)] rounded-[var(--rd-radius-control)] transition-colors " +
  "data-[hovered]:border-[var(--rd-color-border-strong)] " +
  "data-[focus-within]:ring-2 data-[focus-within]:ring-[var(--rd-color-focus-ring)] data-[focus-within]:border-transparent " +
  "data-[invalid]:border-[var(--rd-color-feedback-danger)] " +
  "data-[disabled]:opacity-50 data-[disabled]:cursor-not-allowed";

export const fieldGroupSizes: Record<FieldSize, string> = {
  sm: "h-8 pl-2.5 pr-1 text-sm",
  md: "h-10 pl-3 pr-1 text-sm",
  lg: "h-12 pl-3.5 pr-1.5 text-base",
};

export const segment =
  "rounded px-0.5 tabular-nums outline-none caret-transparent " +
  "data-[placeholder]:text-[var(--rd-color-text-muted)] data-[type=literal]:px-0 data-[type=literal]:text-[var(--rd-color-text-muted)] " +
  "data-[focused]:bg-[var(--rd-color-action-primary)] data-[focused]:text-[var(--rd-color-action-on-primary)]";

export const iconButton =
  "ml-auto flex size-8 shrink-0 items-center justify-center rounded-[var(--rd-radius-control)] outline-none " +
  "text-[var(--rd-color-text-muted)] data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[hovered]:text-[var(--rd-color-text-default)] " +
  "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]";

/** An option row in a Select or Combobox list. */
export const listItem =
  "flex cursor-default items-center justify-between gap-2 rounded-[var(--rd-radius-control)] px-2.5 py-1.5 text-sm outline-none " +
  "text-[var(--rd-color-text-default)] data-[focused]:bg-[var(--rd-color-surface-subtle)] " +
  "data-[selected]:font-medium data-[disabled]:opacity-50";

export const overlayPanel =
  "shadow-lg bg-[var(--rd-color-surface-raised)] text-[var(--rd-color-text-default)] " +
  "border border-[var(--rd-color-border-default)] rounded-[var(--rd-radius-overlay)]";

export function CheckIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 16 16" className="size-4 shrink-0 text-[var(--rd-color-action-primary)]" fill="none">
      <path d="M3.5 8.5l3 3 6-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function ChevronDownIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 16 16" className="size-4 shrink-0 text-[var(--rd-color-text-muted)]" fill="none">
      <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function CloseIcon({ className = "size-3" }: { className?: string }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 16 16" className={className} fill="none">
      <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" />
    </svg>
  );
}

export function Spinner({ className = "size-4" }: { className?: string }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" className={`${className} animate-spin`} fill="none">
      <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" opacity="0.25" />
      <path d="M22 12a10 10 0 0 0-10-10" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
    </svg>
  );
}

export function CalendarIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 16 16" className="size-4" fill="none">
      <rect x="2.5" y="3.5" width="11" height="10" rx="1.5" stroke="currentColor" strokeWidth="1.3" />
      <path d="M2.5 6.5h11M5.5 2v3M10.5 2v3" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
    </svg>
  );
}

// Status icons for Alert. Each tone has its own shape (circle with i, check,
// triangle, octagon) so the tone never depends on color alone.
const statusIcon = "size-5 shrink-0";

export function InfoIcon({ className = statusIcon }: { className?: string }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 20 20" className={className} fill="none">
      <circle cx="10" cy="10" r="8" stroke="currentColor" strokeWidth="1.6" />
      <path d="M10 9v5M10 6.25v.01" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  );
}

export function SuccessIcon({ className = statusIcon }: { className?: string }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 20 20" className={className} fill="none">
      <circle cx="10" cy="10" r="8" stroke="currentColor" strokeWidth="1.6" />
      <path d="M6.5 10.25l2.5 2.5 4.5-5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function WarningIcon({ className = statusIcon }: { className?: string }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 20 20" className={className} fill="none">
      <path d="M10 2.75l8 14H2l8-14z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
      <path d="M10 8v4M10 14.25v.01" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  );
}

export function ErrorIcon({ className = statusIcon }: { className?: string }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 20 20" className={className} fill="none">
      <path d="M7 2.5h6l4.5 4.5v6L13 17.5H7L2.5 13V7L7 2.5z" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" />
      <path d="M7.5 7.5l5 5M12.5 7.5l-5 5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  );
}

"use client";

import { useSyncExternalStore } from "react";

/**
 * True while `query` matches. On the server (and during hydration) it
 * returns `serverValue`, so pick the value your mobile-first layout expects.
 */
export function useMediaQuery(query: string, serverValue = false): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const list = window.matchMedia(query);
      list.addEventListener("change", onChange);
      return () => list.removeEventListener("change", onChange);
    },
    () => window.matchMedia(query).matches,
    () => serverValue,
  );
}
